const event = $input.first().json;
const text = (value) => String(value ?? '').trim();
const orderNumber = text(event.order_number);
const email = text(event.email);
const productId = text(event.product_id);
const priceText = text(event.price);
const amount = Number(priceText.replace(',', '.'));
const currency = text(event.currency);
const productName = text(event.product_name);
const saleDate = text(event.sale_timestamp);
const errors = [];
if (!orderNumber) errors.push('Missing order_number');
if (!email) errors.push('Missing email');
if (!productId) errors.push('Missing product_id');
if (!priceText || !Number.isFinite(amount) || amount < 0) errors.push('Invalid price');
if (!currency) errors.push('Missing currency');
if (saleDate && Number.isNaN(Date.parse(saleDate))) errors.push('Invalid sale_timestamp');
if (errors.length) throw new Error(`Sale rejected before Airtable write: ${errors.join('; ')}`);
const fields = {
  'Order Number': orderNumber,
  'Buyer Email': email,
  'Product ID': productId,
  'Product Name': productName,
  'Sale Amount': amount,
  'Currency': currency,
};
if (saleDate) fields['Sale Date'] = saleDate;
return [{ json: { requestBody: { performUpsert: { fieldsToMergeOn: ['Order Number'] }, records: [{ fields }] } } }];
